    scripts['UA29ST/KMR-1-033'] = scripts['UA29BT/KMR-1-033'];

    if (typeof window.registerCardScripts === 'function') window.registerCardScripts(scripts);
    else window.UACardScripts = Object.assign(window.UACardScripts || {}, scripts);
