            engine.executeAbilityActions(cardEl, [
                { type: 'LOOK_AND_ARRANGE_TOP', count: cnt, keepUpTo: cnt, upTo: true, remainderTo: 'OUTSIDE' }
            ], 0, { selectedTargets: [], addedFromLook: false }, onComplete);
